  roles: string[];
  asks: DensityAskCost[];
  /** Every interaction added, over the asks; never reduced by scroll saved anywhere. */
  interactionsAdded: number;
  /** Asks whose reach is known before and not after, or the reverse: their cost is unknown. */
  unknownAsks: string[];
