// ============================================================================
// One cell's reading
// ============================================================================

interface CellContext {
  capture: DensityCapture;
  report: DensityMeasureReport;
  targets: DensityTargets | null;
  floors: DensityFloors | null;
  byId: Map<string, DensityItem>;
  children: Map<string, string[]>;
  leaves: DensityLeaves;
  pins: DensityPins;
  placed: Map<string, DensityRect>;
  blocks: DensityBlock[];
  classes: DensityClassification;
  repeats: DensityRepeat[];
  /** Answering item ids of each ask with a resolved answer. */
  answers: Map<string, string[]>;
}

interface Candidate {
  id: string;
  generator: DensityGenerator;
  subject: string[];
  evidence: DensityProposalEvidence;
  edits: DensityEdit[] | null;
  /** Why no edit is stated, when `edits` is `null`. */
  noEdit: { code: UnknownCode; reason: string } | null;
}

function extentOf(rects: readonly DensityRect[]): DensityRect | null {
  if (rects.length === 0) return null;
  const x = Math.min(...rects.map((r) => r.x));
  const y = Math.min(...rects.map((r) => r.y));
  const right = Math.max(...rects.map((r) => r.x + r.w));
  const bottom = Math.max(...rects.map((r) => r.y + r.h));
  return { x, y, w: right - x, h: bottom - y };
}

function extentOfIds(ctx: CellContext, ids: Iterable<string>): DensityRect | null {
  const rects: DensityRect[] = [];
  for (const id of ids) {
    const r = ctx.placed.get(id);
    if (r) rects.push(r);
  }
  return extentOf(rects);
}

/** The uncertain weight that keeps a claimed weight from being known. */
function uncertainWeight(report: DensityMeasureReport): number {
  return report.role ? report.role.unresolvedWeight + report.role.unplacedWeight : 0;
}

function evidence(
  ctx: CellContext,
  trigger: string,
  values: DensityProposalEvidence['values']
): DensityProposalEvidence {
  return { cell: ctx.capture.cell, trigger, values };
}

function syntheticIds(id: string): { toggle: string; container: string; finder: string } {
  return {
    toggle: `density-plan:${id}:toggle`,
    container: `density-plan:${id}:content`,
    finder: `density-plan:${id}:finder`,
  };
}

/**
 * A collapse of `members`. Its summary row is one line of the first member
 * that has a place: that member's line height, else its height.
 */
function collapseOf(ctx: CellContext, id: string, members: string[]): DensityEdit | null {
  const first = members.find((m) => ctx.placed.has(m));
  if (first === undefined) return null;
  const rect = ctx.placed.get(first)!;
  const line = ctx.byId.get(first)?.lineHeightPx ?? null;
  const summaryPx = line !== null && line > 0 ? Math.min(line, rect.h) : rect.h;
  if (!(summaryPx > 0)) return null;
  const ids = syntheticIds(id);
  return {
    op: 'collapse',
    subject: members,
    summaryPx,
    toggle: ids.toggle,
    container: ids.container,
  };
}

// ---- demote ----
function demote(ctx: CellContext): Candidate[] {
  if (!ctx.report.unclaimed) return [];
  const out: Candidate[] = [];
  const reports = new Map(ctx.report.blocks.list.map((b) => [b.id, b]));
  for (const u of ctx.report.unclaimed.list) {
    const block = ctx.blocks.find((b) => b.id === u.block);
    const ext = block && extentOfIds(ctx, block.members);
    if (!block || !ext) continue;
    let last: DensityBlock | null = null;
    for (const o of ctx.blocks) {
      if (o === block || (reports.get(o.id)?.claimedWeight ?? 0) <= 0) continue;
      const eo = extentOfIds(ctx, o.members);
      if (!eo || eo.y <= ext.y || !densitySameColumn(ext, eo)) continue;
      if (last === null || (o.topPx ?? -Infinity) > (last.topPx ?? -Infinity)) last = o;
    }
    const id = `demote:${block.id}`;
    const edit: DensityEdit | null = last
      ? { op: 'move', subject: block.members, below: last.members }
      : collapseOf(ctx, id, block.members);
    if (!edit) continue;
    out.push({
      id,
      generator: 'demote',
      subject: block.members,
      evidence: evidence(
        ctx,
        'firstScreenPx > 0, claimedWeight = 0 and displacementPx > 0 (the unclaimed-block observation)',
        {
          block: block.id,
          firstScreenPx: u.firstScreenPx,
          claimedWeight: 0,
          displacementPx: u.displacementPx,
          movedBelow: last?.id ?? null,
        }
      ),
      edits: [edit],
      noEdit: null,
    });
  }
  return out;
}

// ---- order ----
function order(ctx: CellContext): Candidate[] {
  if (!ctx.report.role || uncertainWeight(ctx.report) > 0) return [];
  const reports = new Map(ctx.report.blocks.list.map((b) => [b.id, b]));
  const top = ctx.blocks
    .filter((b) => b.parent === null && b.topPx !== null && b.pitchPx !== null && b.pitchPx > 0)
    .map((b) => ({ b, ext: extentOfIds(ctx, b.members), r: reports.get(b.id) }))
    .filter(
      (x): x is { b: DensityBlock; ext: DensityRect; r: NonNullable<typeof x.r> } =>
        x.ext !== null && x.r !== undefined
    )
    .sort((a, b) => a.ext.y - b.ext.y);
  const ratio = (x: (typeof top)[number]) => (x.r.claimedWeight ?? 0) / (x.b.pitchPx as number);
  const out: Candidate[] = [];
  for (let i = 0; i < top.length; i++) {
    const a = top[i];
    // The next block below it in its column.
    const next = top.slice(i + 1).find((o) => o.ext.y > a.ext.y && densitySameColumn(a.ext, o.ext));
    if (!next || !(ratio(a) < ratio(next))) continue;
    out.push({
      id: `order:${a.b.id}>${next.b.id}`,
      generator: 'order',
      subject: a.b.members,
      evidence: evidence(
        ctx,
        'two consecutive blocks of a column not in descending claimedWeight / pitchPx',
        {
          upper: a.b.id,
          upperClaimedWeight: a.r.claimedWeight ?? 0,
          upperPitchPx: a.b.pitchPx,
          lower: next.b.id,
          lowerClaimedWeight: next.r.claimedWeight ?? 0,
          lowerPitchPx: next.b.pitchPx,
        }
      ),
      edits: [{ op: 'move', subject: a.b.members, below: next.b.members }],
      noEdit: null,
    });
  }
  return out;
}

/** A repeat's members grouped into rows, top to bottom. */
function rowsOf(ctx: CellContext, r: DensityRepeat): string[][] {
  const members = r.members
    .map((id) => ({ id, rect: ctx.byId.get(id)?.rect ?? null }))
    .filter((m): m is { id: string; rect: DensityRect } => m.rect !== null)
    .sort((a, b) => a.rect.y - b.rect.y);
  const rows: Array<{ top: number; bottom: number; ids: string[] }> = [];
  for (const m of members) {
    const cur = rows[rows.length - 1];
    if (
      cur &&
      (Math.abs(m.rect.y - cur.top) <= DENSITY_REPEAT_TOLERANCE_PX || m.rect.y < cur.bottom)
    ) {
      cur.ids.push(m.id);
      cur.bottom = Math.max(cur.bottom, m.rect.y + m.rect.h);
    } else rows.push({ top: m.rect.y, bottom: m.rect.y + m.rect.h, ids: [m.id] });
  }
  return rows.map((row) => row.ids);
}

/** The leaves at or below some ids, with rects, in capture order. */
function leavesBelow(ctx: CellContext, ids: readonly string[]): DensityItem[] {
  const sub = densitySubtree(ctx.capture, ids, ctx.children);
  const leafIds = new Set(ctx.leaves.ids);
  return ctx.capture.items.filter((i) => sub.has(i.id) && leafIds.has(i.id) && i.rect !== null);
}

/** The pitch a row may not go under: `max(lines · fontPx · lineHeightRatio + 2 · rowPadPx, targetPx with a control)`. */
function floorPitch(f: DensityFloors, lines: number, fontPx: number, control: boolean): number {
  return Math.max(lines * fontPx * f.lineHeightRatio + 2 * f.rowPadPx, control ? f.targetPx : 0);
}

function rowFacts(ctx: CellContext, r: DensityRepeat) {
  const rows = rowsOf(ctx, r);
  const leaves = rows.flatMap((row) => leavesBelow(ctx, row));
  const fonts = leaves.map((l) => l.fontPx).filter((f): f is number => f !== null);
  const sub = densitySubtree(ctx.capture, r.members, ctx.children);
  const control = ctx.capture.items.some((i) => sub.has(i.id) && i.interactive);
  // The most any row's leaves reach below its top: leaves keep their size and
  // their place in the row (no-rewrap), so no pitch goes under it.
  let bandPx = 0;
  for (const row of rows) {
    const ls = leavesBelow(ctx, row);
    const top = extentOfIds(ctx, row)?.y;
    if (ls.length === 0 || top === undefined) continue;
    bandPx = Math.max(bandPx, Math.max(...ls.map((l) => l.rect!.y + l.rect!.h)) - top);
  }
  return { rows, fontPx: fonts.length > 0 ? Math.max(...fonts) : null, control, bandPx };
}

function noFloors(what: string): { code: UnknownCode; reason: string } {
  return {
    code: 'no_expectation',
    reason: `${what} is a compaction, which is planned against floors, and none were given`,
  };
}

// ---- pitch ----
/** Each row's own pitch: its top to the next row's top; the last row takes the repeat's median. */
function ownPitches(ctx: CellContext, rows: string[][], median: number): number[] {
  const tops = rows.map((row) => extentOfIds(ctx, row)?.y ?? null);
  return rows.map((_, i) => {
    const t = tops[i];
    const n = tops[i + 1];
    return t !== null && n !== null && n !== undefined ? n - t : median;
  });
}

function fontUnknown(what: string): { code: UnknownCode; reason: string } {
  return {
    code: 'input_missing',
    reason: `${what} is planned against the row's font size, which the capture does not carry, so its floor pitch is unknown`,
  };
}

function pitch(ctx: CellContext): Candidate[] {
  const out: Candidate[] = [];
  for (const r of ctx.repeats) {
    if (r.linesPerRow === null || r.rowTextPx === null || r.rows < 2) continue;
    const { rows, fontPx, control, bandPx } = rowFacts(ctx, r);
    if (fontPx === null) {
      if (!(r.rowPitchPx > r.rowTextPx + EPS)) continue;
      out.push({
        id: `pitch:${r.id}`,
        generator: 'pitch',
        subject: r.members,
        evidence: evidence(ctx, 'rowPitchPx exceeds rowTextPx, and the row font is unknown', {
          repeat: r.id,
          rowPitchPx: r.rowPitchPx,
          rowTextPx: r.rowTextPx,
          fontPx: null,
        }),
        edits: null,
        noEdit: ctx.floors === null ? noFloors('pitch') : fontUnknown('pitch'),
      });
      continue;
    }
    const lines = Math.max(1, Math.round(r.linesPerRow));
    const id = `pitch:${r.id}`;
    const values = {
      repeat: r.id,
      rows: r.rows,
      rowPitchPx: r.rowPitchPx,
      rowTextPx: r.rowTextPx,
      linesPerRow: r.linesPerRow,
      fontPx,
      holdsControl: control,
    };
    if (ctx.floors === null) {
      // Without floors the trigger is the pitch exceeding the text it holds.
      if (!(r.rowPitchPx > r.rowTextPx + EPS)) continue;
      out.push({
        id,
        generator: 'pitch',
        subject: r.members,
        evidence: evidence(
          ctx,
          'rowPitchPx exceeds rowTextPx (no floors were given to plan the pitch against)',
          values
        ),
        edits: null,
        noEdit: noFloors('pitch'),
      });
      continue;
    }
    // The floor pitch, and never under the row's own leaves.
    const target = Math.max(floorPitch(ctx.floors, lines, fontPx, control), bandPx);
    if (!(r.rowPitchPx > target + EPS)) continue;
    // Each row from its own pitch to the target: a row already at or under it is left alone.
    const own = ownPitches(ctx, rows, r.rowPitchPx);
    const edits: DensityEdit[] = rows
      .map((row, i) => ({ op: 'resize' as const, subject: row, deltaPx: target - own[i] }))
      .filter((e) => e.deltaPx < -EPS);
    if (edits.length === 0) continue;
    out.push({
      id,
      generator: 'pitch',
      subject: r.members,
      evidence: evidence(
        ctx,
        'rowPitchPx > max(lines · fontPx · lineHeightRatio + 2 · rowPadPx, targetPx if a row holds a control), and above the row band its leaves keep',
        { ...values, rowBandPx: bandPx, targetPitchPx: target }
      ),
      edits,
      noEdit: null,
    });
  }
  return out;
}

// ---- one-line ----
function oneLine(ctx: CellContext): Candidate[] {
  const out: Candidate[] = [];
  const kindOf = new Map(ctx.classes.items.map((c) => [c.id, c.kind]));
  for (const r of ctx.repeats) {
    if (r.linesPerRow === null || !(r.linesPerRow > 1 + 1e-9)) continue;
    const { rows, fontPx, control } = rowFacts(ctx, r);
    const id = `one-line:${r.id}`;
    const values: DensityProposalEvidence['values'] = {
      repeat: r.id,
      rows: r.rows,
      linesPerRow: r.linesPerRow,
      rowPitchPx: r.rowPitchPx,
    };
    const plans = rows.map((row) => {
      const leaves = leavesBelow(ctx, row);
      const width = extentOfIds(ctx, densitySubtree(ctx.capture, row, ctx.children))?.w ?? 0;
      const need =
        leaves.reduce((s, l) => s + l.rect!.w, 0) + DENSITY_LINE_UP_GAP_PX * (leaves.length - 1);
      return { row, leaves, width, need };
    });
    if (plans.every((p) => p.leaves.length < 2)) continue;
    const fits = plans.every((p) => p.need <= p.width + EPS);
    const edits: DensityEdit[] = [];
    let form: 'line-up' | 'abbreviate' = 'line-up';
    let infeasible: string | null = null;
    for (const p of plans) {
      if (p.leaves.length < 2) continue;
      if (p.need > p.width + EPS) {
        form = 'abbreviate';
        const labels = p.leaves.filter((l) => kindOf.get(l.id) === 'label');
        const widest = labels.sort((a, b) => b.rect!.w - a.rect!.w)[0];
        const narrowed = widest ? widest.rect!.w - (p.need - p.width) : 0;
        // A label narrower than two em of its own font is no longer read.
        if (!widest || widest.fontPx === null || narrowed < 2 * widest.fontPx) {
          infeasible = !widest
            ? 'a row does not fit side by side and holds no label to abbreviate'
            : widest.fontPx === null
              ? 'a row does not fit side by side and its widest label has no known font size'
              : 'a row does not fit side by side even with its widest label at two em';
          break;
        }
        edits.push({ op: 'abbreviate', item: widest.id, widthPx: narrowed });
      }
      edits.push({ op: 'line-up', row: p.row, gapPx: DENSITY_LINE_UP_GAP_PX });
    }
    values.form = form;
    values.fits = fits;
    const trigger =
      'linesPerRow > 1 and the row leaves fit its width side by side, or would with its widest label abbreviated';
    if (infeasible !== null) {
      out.push({
        id,
        generator: 'one-line',
        subject: r.members,
        evidence: evidence(ctx, 'linesPerRow > 1', values),
        edits: null,
        // Without floors a compaction is unknown{no_expectation} first of all.
        noEdit:
          ctx.floors === null
            ? noFloors('one-line')
            : { code: 'not_attempted_by_policy', reason: infeasible },
      });
      continue;
    }
    if (ctx.floors !== null && fontPx === null) {
      out.push({
        id,
        generator: 'one-line',
        subject: r.members,
        evidence: evidence(ctx, trigger, values),
        edits: null,
        noEdit: fontUnknown('one-line'),
      });
      continue;
    }
    if (ctx.floors === null) {
      out.push({
        id,
        generator: 'one-line',
        subject: r.members,
        evidence: evidence(
          ctx,
          'linesPerRow > 1 and the row leaves fit its width side by side, or would with its widest label abbreviated',
          values
        ),
        edits: null,
        noEdit: noFloors('one-line'),
      });
      continue;
    }
    // Never under the floor: a row lined up below its floor pitch is held at it.
    if (fontPx !== null) {
      const floor = floorPitch(ctx.floors, 1, fontPx, control);
      const own = ownPitches(ctx, rows, r.rowPitchPx);
      for (const [i, p] of plans.entries()) {
        if (p.leaves.length < 2) continue;
        const tallest = Math.max(...p.leaves.map((l) => l.rect!.h));
        const band =
          Math.max(...p.leaves.map((l) => l.rect!.y + l.rect!.h)) -
          Math.min(...p.leaves.map((l) => l.rect!.y));
        const newPitch = own[i] - (band - tallest);
        if (newPitch < floor - EPS)
          edits.push({ op: 'resize', subject: p.row, deltaPx: floor - newPitch });
      }
    }
    out.push({
      id,
      generator: 'one-line',
      subject: r.members,
      evidence: evidence(
        ctx,
        'linesPerRow > 1 and the row leaves fit its width side by side, or would with its widest label abbreviated',
        values
      ),
      edits,
      noEdit: null,
    });
  }
  return out;
}

// ---- chrome ----
function chrome(ctx: CellContext): Candidate[] {
  const navs = new Map<string, string[]>();
  for (const item of ctx.capture.items) {
    const key =
      densityNavPrefix(item) ?? (item.landmark === 'navigation' ? 'landmark:navigation' : null);
    if (key === null) continue;
    const list = navs.get(key);
    if (list) list.push(item.id);
    else navs.set(key, [item.id]);
  }
  const out: Candidate[] = [];
  for (const [key, ids] of navs) {
    const controls = ids
      .map((id) => ctx.byId.get(id)!)
      .filter((i) => isDensityNavControl(i) && i.rect !== null);
    if (controls.length < 2) continue;
    const ext = extentOfIds(ctx, ids);
    const controlPx = Math.max(...controls.map((c) => c.rect!.h));
    if (!ext || !(ext.h > controlPx + EPS) || controlPx <= 0) continue;
    const id = `chrome:${ids[0]}`;
    const s = syntheticIds(id);
    out.push({
      id,
      generator: 'chrome',
      subject: ids,
      evidence: evidence(ctx, 'a navigation taller than one of its controls at this viewport', {
        navigation: key,
        heightPx: ext.h,
        controlPx,
        controls: controls.length,
      }),
      edits: [
        {
          op: 'collapse',
          subject: ids,
          summaryPx: controlPx,
          toggle: s.toggle,
          container: s.container,
        },
      ],
      noEdit: null,
    });
  }
  return out;
}

// ---- disclose ----
function disclose(ctx: CellContext): Candidate[] {
  const role = ctx.report.role;
  if (!role || uncertainWeight(ctx.report) > 0) return [];
  const askById = new Map(role.asks.map((a) => [a.id, a]));
  const out: Candidate[] = [];
  for (const b of ctx.blocks) {
    const members = new Set(b.members);
    const claiming: DensityAskReach[] = [];
    for (const [askId, items] of ctx.answers) {
      if (items.some((i) => members.has(i))) claiming.push(askById.get(askId)!);
    }
    if (claiming.length === 0 || !claiming.every((a) => a.kind === 'reference')) continue;
    if (b.members.every((m) => ctx.byId.get(m)?.visibility === 'hidden')) continue;
    const id = `disclose:${b.id}`;
    const edit = collapseOf(ctx, id, b.members);
    if (
      !edit ||
      edit.op !== 'collapse' ||
      b.heightPx === null ||
      b.heightPx <= edit.summaryPx + EPS
    )
      continue;
    out.push({
      id,
      generator: 'disclose',
      subject: b.members,
      evidence: evidence(ctx, 'a block answered only by reference asks', {
        block: b.id,
        asks: claiming.map((a) => a.id).join(','),
        heightPx: b.heightPx,
      }),
      edits: [edit],
      noEdit: null,
    });
  }
  return out;
}

// ---- find ----
function find(ctx: CellContext, volume: number | null): Candidate[] {
  const role = ctx.report.role;
  if (!role) return [];
  const out: Candidate[] = [];
  const seen = new Set<string>();
  const finderHeight = (): number | null => {
    const existing = ctx.capture.items.find(
      (i) => isDensityFinderControl(i) && i.rect !== null && i.rect.h > 0
    );
    if (existing) return existing.rect!.h;
    return ctx.floors?.targetPx ?? null;
  };
  for (const a of role.asks) {
    if (a.kind !== 'lookup' || (a.state !== 'rendered' && a.state !== 'hidden')) continue;
    const items = new Set(ctx.answers.get(a.id) ?? []);
    for (const r of ctx.repeats) {
      if (r.finder !== null || seen.has(r.id)) continue;
      const sub = densitySubtree(ctx.capture, r.members, ctx.children);
      if (![...items].some((i) => sub.has(i))) continue;
      const atVolume = 'px' in r.extentAtVolume ? r.extentAtVolume.px : null;
      const heightPx = atVolume ?? r.extentPx;
      if (!(heightPx > ctx.pins.usableHeightPx + EPS)) continue;
      seen.add(r.id);
      const rows = rowsOf(ctx, r);
      const firstRow = rows[0] ?? [];
      const ext = extentOfIds(ctx, firstRow);
      const id = `find:${r.id}`;
      const h = finderHeight();
      const values = {
        ask: a.id,
        repeat: r.id,
        extentPx: heightPx,
        extentBasis: atVolume !== null ? `volume ${volume}` : 'as captured',
        usableHeightPx: ctx.pins.usableHeightPx,
        filteredStateModelled: false,
      };
      const trigger = 'a lookup ask answered in a repeat taller than a screen, with no finder';
      if (h === null || !ext) {
        out.push({
          id,
          generator: 'find',
          subject: r.members,
          evidence: evidence(ctx, trigger, values),
          edits: null,
          noEdit: {
            code: 'no_expectation',
            reason:
              "the finder's height is copied from a text control on the page or the floors' targetPx, and neither is there",
          },
        });
        continue;
      }
      out.push({
        id,
        generator: 'find',
        subject: r.members,
        evidence: evidence(ctx, trigger, values),
        edits: [
          {
            op: 'insert',
            id: syntheticIds(id).finder,
            role: 'searchbox',
            above: firstRow,
            widthPx: ext.w,
            heightPx: h,
          },
        ],
        noEdit: null,
      });
    }
  }
  return out;
}

// ---- dedupe ----
function dedupe(ctx: CellContext): Candidate[] {
  const navHrefs = new Map<string, string>();
  for (const i of ctx.capture.items) {
    if (isDensityNavControl(i) && i.href !== null && !navHrefs.has(i.href))
      navHrefs.set(i.href, i.id);
  }
  const out: Candidate[] = [];
  for (const i of ctx.capture.items) {
    if (!i.interactive || i.href === null || isDensityNavControl(i) || isDensityChrome(i)) continue;
    const nav = navHrefs.get(i.href);
    if (nav === undefined) continue;
    out.push({
      id: `dedupe:${i.id}`,
      generator: 'dedupe',
      subject: [i.id],
      evidence: evidence(ctx, "a content control whose href equals a navigation control's", {
        control: i.id,
        navigationControl: nav,
      }),
      edits: [{ op: 'remove', subject: [i.id] }],
      noEdit: null,
    });
  }
  return out;
}

// ============================================================================
// Prediction and costs
// ============================================================================

function decisive(a: DensityAskReach): { scrollPx: number | null; interactions: number | null } {
  const r = a.need === 'all' ? a.all : a.first;
  return { scrollPx: r?.scrollPx ?? null, interactions: r?.interactions ?? null };
}

/** What a predicted report costs against the measured one, per ask; nothing is netted. */
function costsOf(
  cell: DensityCell,
  before: DensityMeasureReport,
  after: DensityMeasureReport
): DensityCellCosts {
  const costs: DensityCellCosts = {
    cell,
    roles: [],
    asks: [],
    interactionsAdded: 0,
    unknownAsks: [],
  };
  if (!before.role || !after.role) return costs;
  const afterAsks = new Map(after.role.asks.map((a) => [a.id, a]));
  for (const b of before.role.asks) {
    const a = afterAsks.get(b.id);
    if (!a || b.state === 'unanswered') continue;
    const db = decisive(b);
    const da = decisive(a);
    // Unknown on either side: what this ask costs is unknown, never zero.
    if (
      db.interactions === null ||
      da.interactions === null ||
      db.scrollPx === null ||
      da.scrollPx === null
    ) {
      costs.unknownAsks.push(b.id);
    }
    const interactionsAdded =
      db.interactions !== null && da.interactions !== null
        ? Math.max(0, da.interactions - db.interactions)
        : 0;
    const scrollAddedPx =
      db.scrollPx !== null && da.scrollPx !== null ? Math.max(0, da.scrollPx - db.scrollPx) : 0;
    const availabilityLost = b.available === true && a.available !== true;
    if (interactionsAdded > 0 || scrollAddedPx > 0 || availabilityLost) {
      costs.asks.push({ ask: b.id, interactionsAdded, scrollAddedPx, availabilityLost });
      costs.interactionsAdded += interactionsAdded;
    }
  }
  if (costs.asks.length > 0) costs.roles.push(before.role.role);
  return costs;
}

// ============================================================================
// plan
// ============================================================================

/**
 * Plan over the captures of one invocation (one cell each). Every proposal is
 * predicted in every cell, by applying its edits to that cell's capture and
 * measuring the result.
 */
export function planDensity(
  captures: readonly DensityCapture[],
  options: DensityPlanOptions
): DensityPlanReport {
  const targets = options.targets ?? null;
  const floors = options.floors ?? null;
  const volume = options.volume ?? null;
  const evaluatedAt = options.evaluatedAt ?? new Date();
  const measureOpts = {
    producer: options.producer,
    targets,
    floors,
    cap: Number.MAX_SAFE_INTEGER,
    evaluatedAt,
  };
  const measured = captures.map((c) => measureDensity(c, { ...measureOpts, captures }));
  const contexts: Array<CellContext | null> = captures.map((capture, i) => {
    const obs = measured[i];
    if (obs.status !== 'measured' || !capture.structureResolved) return null;
    const leaves = densityLeaves(capture);
    const pins = densityPins(capture);
    const pinned = densityPinnedIds(capture, pins);
    const blocks = densityBlocks(capture, targets, leaves, pinned);
    const classes = classifyDensityItems(capture, targets, leaves, pins);
    const placed = densityPlacedRects(capture, pins);
    const repeats = capture.repeatKeysResolved
      ? densityRepeats(capture, targets, {
          leaves,
          pins,
          blocks,
          classes,
          ...(volume !== null ? { volume } : {}),
        })
      : [];
    const answers = new Map<string, string[]>();
    const declared = targets?.roles.find((r) => r.role === capture.cell.role);
    if (declared) {
      const rc = densityReachContext(capture, pins, leaves, placed, floors);
      for (const ask of declared.asks) {
        const ans = densityAskAnswer(rc, ask);
        if (ans.state === 'rendered' || ans.state === 'hidden') answers.set(ask.id, ans.items);
      }
    }
    return {
      capture,
      report: obs.value,
      targets,
      floors,
      byId: new Map(capture.items.map((it) => [it.id, it])),
      children: densityChildren(capture),
      leaves,
      pins,
      placed,
      blocks: blocks.blocks,
      classes,
      repeats,
      answers,
    };
  });

  // ---- candidates, merged across cells ----
  const candidates: Candidate[] = [];
  const evidenceById = new Map<string, DensityProposalEvidence[]>();
  for (const ctx of contexts) {
    if (ctx === null) continue;
    const found = [
      ...demote(ctx),
      ...order(ctx),
      ...pitch(ctx),
      ...oneLine(ctx),
      ...chrome(ctx),
      ...disclose(ctx),
      ...find(ctx, volume),
      ...dedupe(ctx),
    ];
    for (const c of found) {
      const sameEdits = candidates.find(
        (x) => x.id === c.id && JSON.stringify(x.edits) === JSON.stringify(c.edits)
      );
      if (sameEdits) {
        evidenceById.get(sameEdits.id)!.push(c.evidence);
        continue;
      }
      // The same proposal with different edits in another cell is its own proposal.
      const id = candidates.some((x) => x.id === c.id)
        ? `${c.id}@${densityCellLabel(ctx.capture.cell)}`
        : c.id;
      candidates.push({ ...c, id });
      evidenceById.set(id, [c.evidence]);
    }
  }

  // ---- predictions ----
  const beforeQuantities = measured.map((m) =>
    m.status === 'measured' ? densityReportQuantities(m.value) : null
  );
  const hashes = captures.map((c) => densityCaptureHash(c));
  const proposals: DensityProposal[] = candidates.map((c) => {
    const predicted: DensityProposal['predicted'] = [];
    const costs: DensityProposal['costs'] = [];
    captures.forEach((capture, i) => {
      const prov = Observation.provenance({
        producer: { id: options.producer.id, version: options.producer.version },
        observedAt: capture.observedAt,
        evaluatedAt,
        coverage: capture.coverage,
        source: {
          package: options.producer.package,
          reflow: DENSITY_REFLOW,
          fromCapture: hashes[i],
        },
      });
      const unknown = (code: UnknownCode, reason: string) => {
        predicted.push({
          cell: capture.cell,
          observation: Observation.unknown(code, reason, prov),
        });
        costs.push({ cell: capture.cell, costs: null });
      };
      const before = measured[i];
      if (c.edits === null) return unknown(c.noEdit!.code, c.noEdit!.reason);
      if (before.status !== 'measured')
        return unknown('input_missing', 'this cell could not be measured');
      const applied = applyDensityEdits(capture, c.edits);
      if (!applied.ok) return unknown(applied.unknown, applied.reason);
      const after = measureDensity(applied.capture, {
        ...measureOpts,
        captures: [applied.capture],
      });
      if (after.status !== 'measured') {
        return unknown('input_missing', 'the edited capture could not be measured');
      }
      const { deltas, unchanged, unknownBoth } = densityDeltas(
        beforeQuantities[i]!,
        densityReportQuantities(after.value)
      );
      // The bounds as a report prints them: their leaf lists capped.
      const shownAfter = measureDensity(applied.capture, {
        ...measureOpts,
        cap: undefined,
        captures: [applied.capture],
      });
      const bounds =
        shownAfter.status === 'measured' ? shownAfter.value.bounds : after.value.bounds;
      predicted.push({
        cell: capture.cell,
        observation: Observation.measured(
          {
            cell: capture.cell,
            reflow: applied.reflow,
            assumptions: applied.assumptions,
            fromCapture: hashes[i],
            targetsHash: targets ? densityTargetsHash(targets) : null,
            floors,
            deltas,
            unchanged,
            unknownBoth,
            bounds,
          },
          prov
        ),
      });
      costs.push({ cell: capture.cell, costs: costsOf(capture.cell, before.value, after.value) });
    });
    return {
      id: c.id,
      generator: c.generator,
      compaction: DENSITY_COMPACTIONS.includes(c.generator),
      subject: c.subject,
      evidence: evidenceById.get(c.id)!,
      edits: c.edits,
      reflow: DENSITY_REFLOW,
      assumptions: [...DENSITY_EDIT_ASSUMPTIONS],
      predicted,
      costs,
      conflicts: [],
    };
  });

  // ---- conflicts ----
  const touched = proposals.map(
    (p) => new Set(p.edits ? p.edits.flatMap(densityEditSubjects) : p.subject)
  );
  proposals.forEach((p, i) => {
    p.conflicts = proposals
      .filter((_, j) => j !== i && [...touched[j]].some((id) => touched[i].has(id)))
      .map((o) => o.id);
  });

  // ---- order: unranked unless the caller names one ----
  const orderedBy = options.orderedBy ?? null;
  let list = proposals;
  if (orderedBy !== null) {
    const known = beforeQuantities[orderedBy.cell];
    if (!known || !known.has(orderedBy.quantity)) {
      throw new DensityPlanError(
        `orderedBy names ${orderedBy.quantity}, which cell ${orderedBy.cell} does not report`
      );
    }
    const key = (p: DensityProposal): number | null => {
      const cell = p.predicted[orderedBy.cell];
      if (!cell || cell.observation.status !== 'measured') return null;
      const d = cell.observation.value.deltas.find((x) => x.quantity === orderedBy.quantity);
      const v: DensityDeltaValue = d === undefined ? 0 : d.delta;
      if (v === null) return null;
      if (typeof v === 'number') return v;
      // An interval orders by its end that is worst for the chosen direction.
      return orderedBy.direction === 'descending' ? v.lo : v.hi;
    };
    list = proposals
      .map((p, i) => ({ p, i, k: key(p) }))
      .sort((a, b) => {
        if (a.k === null || b.k === null)
          return a.k === null && b.k === null ? a.i - b.i : a.k === null ? 1 : -1;
        const d = orderedBy.direction === 'descending' ? b.k - a.k : a.k - b.k;
        return d !== 0 ? d : a.i - b.i;
      })
      .map((x) => x.p);
  }

  const byGenerator = Object.fromEntries(DENSITY_GENERATORS.map((g) => [g, 0])) as Record<
    DensityGenerator,
    number
  >;
  for (const p of proposals) byGenerator[p.generator]++;
  const cap = options.cap ?? DENSITY_PROPOSAL_LIST_CAP;
  const shown = list.slice(0, Math.max(0, cap));
  return {
    reflow: DENSITY_REFLOW,
    orderedBy,
    floorsGiven: floors !== null,
    // Each cell as `measure` prints it, its lists capped.
    cells: captures.map((c) => ({
      cell: c.cell,
      observation: measureDensity(c, { ...measureOpts, cap: undefined, captures }),
    })),
    byGenerator,
    proposals: {
      shown: shown.length,
      total: list.length,
      truncated: shown.length < list.length,
      list: shown,
    },
  };
}
